from pathlib import Path
import json,gzip,hashlib,sys,os,subprocess,tempfile,numpy as np
R=Path.cwd();E=R/'work/evidence/AT10/2026-10-15-f3-head-r1';A=R/'atlas-data/anatomy/skin/at10-f3-head-r1';sys.path.insert(0,str(R/'work/tools'));from at10_skin_field_math import landmark_flow_operator
rev=sys.argv[1] if len(sys.argv)>1 else 'f3c11';recipe=json.loads(gzip.decompress((E/f'recipe-{rev}.json.gz').read_bytes()));basePath=R/recipe['baseCandidate'];assert hashlib.sha256(basePath.read_bytes()).hexdigest()==recipe['baseCandidateSha256'];d=json.loads(basePath.read_text());source=np.array(d['sourceVertices']);raw=R/'atlas-data/source-cache/datasets/skin-source-review-2026-10-13/base.obj';assert hashlib.sha256(raw.read_bytes()).hexdigest()=='8e761e6624b8f54536409135d1636da63b32486a90d4897f84e121d144f6fb4c';core=np.array([list(map(float,x.split()[1:4])) for x in raw.read_text().splitlines() if x.startswith('v ')])*.1;w=np.clip((source[:,1]-.50)/.08,0,1);w=w*w*(3-2*w);source+=w[:,None]*(core[d['originalVertexIds']]-source);ids=np.array(recipe['sourceUnitVertices']);positions=np.array(d['positions']);positions[ids]=landmark_flow_operator(recipe)(source[ids])[0];roots=np.array(recipe.get('collarBandFixedLogicalVertices',recipe['actualTopologicalBoundary']));positions[roots]=np.array(d['positions'])[roots];d['sourceVertices']=source.tolist();d['positions']=positions.tolist();d['candidateRevision']=rev;tmp=Path(tempfile.mkdtemp(prefix='at10-f3-reproduction-',dir='/private/tmp'));(tmp/'candidates').mkdir();(tmp/f'candidates/fit-{rev}.json').write_text(json.dumps(d,separators=(',',':'))+'\n');env=dict(os.environ,AT10_SKIN_EVIDENCE=str(tmp),AT10_SKIN_ARTIFACTS=str(tmp/'artifacts'));run=subprocess.run([sys.executable,str(R/'work/tools/export_at10_skin.py'),'--revision',rev],env=env,capture_output=True,text=True);assert run.returncode==0,run.stderr;old=(A/f'skin-candidate-{rev}.glb').read_bytes();new=(tmp/f'artifacts/skin-candidate-{rev}.glb').read_bytes();assert old==new,'actual emitted GLB is not byte-exact reproduced';out={'sourceCoreAndOutsideF2Replayed':True,'finalCandidatePositionsUsedAsInput':False,'float32GlbByteExact':True,'sha256':hashlib.sha256(new).hexdigest(),'bytes':len(new),'temporaryOutput':str(tmp),'sourceToMetreScaleAppliedOnce':.1,'recipeCompressedSha256':hashlib.sha256((E/f'recipe-{rev}.json.gz').read_bytes()).hexdigest()};(E/f'reproduction-{rev}.json').write_text(json.dumps(out,indent=2)+'\n');print(out)
